function load(){try{let s=JSON.parse(localStorage.getItem('our-little-world-save'));if(s?.version===1){let base=fresh();let houseItems=Array.isArray(s.houseItems)?s.houseItems:base.houseItems;if(!Array.isArray(s.houseItems)&&(s.furniture||[]).includes('plant')&&!houseItems.some(o=>o.id==='plant'&&o.room==='home'))houseItems.push({id:'plant',room:'home',x:790});return {...base,...s,heroes:base.heroes.map((p,i)=>({...p,...(s.heroes?.[i]||{})})),needs:base.needs.map((n,i)=>({...n,...(s.needs?.[i]||{})})),houseItems,settings:{...base.settings,...(s.settings||{})},anniversary:{...base.anniversary,...(s.anniversary||{}),memories:Array.isArray(s.anniversary?.memories)?s.anniversary.memories:[]}}}}catch{}return fresh()}
function save(){try{const snapshot=JSON.parse(JSON.stringify(game));delete snapshot.pairRunning;if(snapshot.anniversary){delete snapshot.anniversary.giftOpening;delete snapshot.anniversary.finalPending;delete snapshot.anniversary.fireworksAt;delete snapshot.anniversary.fireworksUntil}snapshot.heroes.forEach(p=>{delete p.approach;delete p.actionTime;delete p.pairKind;if(p.action?.startsWith('romance-'))p.action=null});localStorage.setItem('our-little-world-save',JSON.stringify(snapshot));return true}catch{notify('Не удалось сохранить игру в этом браузере.');return false}}
