function drawDoor(){const x=906-game.camera,y=scenes[game.scene].ground;rect(x-20,y-99,40,99,'#78533e');rect(x-15,y-94,30,91,'#b88760');rect(x-10,y-87,20,36,'#94b9b2');rect(x+7,y-47,3,3,'#f0d387');rect(x-22,y-101,44,6,'#684b39');rect(x-24,y-4,48,4,'#5f4838')}
function drawCharacter(p,index,t){
 const x=Math.round(p.x-game.camera),g=scenes[game.scene].ground,jump=Math.max(0,p.jumpY||0),facing=p.facing||1;
 const state=p.anim?.state||'idle',source=spriteSource(p,state,p.anim?.time||t/1000);
 // A compact shadow remains anchored to the foot position as the sprite hops.
 ctx.fillStyle=`rgba(41,70,62,${Math.max(.15,.3-jump/180)})`;ctx.beginPath();ctx.ellipse(x,g+2,Math.max(9,17-jump*.14),4,0,0,Math.PI*2);ctx.fill();
 const draw=(frame,alpha)=>{ctx.save();ctx.globalAlpha*=alpha;if(p.action==='bed'){ctx.translate(x,g-24-jump);ctx.rotate(facing<0?Math.PI/2:-Math.PI/2);ctx.drawImage(frame.image,frame.sx,frame.sy,frame.sw,frame.sh,-44,-24,88,48)}else{if(facing<0){ctx.translate(x*2,0);ctx.scale(-1,1)}const seated=['sofa','armchair','chair','dining_table','coffee_table','tub','sink','toilet','romance-sit'].includes(p.action),h=seated?64:SPRITE.height*SPRITE.scale;ctx.drawImage(frame.image,frame.sx,frame.sy,frame.sw,frame.sh,x-12*SPRITE.scale,g-h-jump,SPRITE.width*SPRITE.scale,h)}ctx.restore()};
 if(p.anim&&p.anim.blend<1){draw(spriteSource(p,p.anim.from,p.anim.fromTime),1-p.anim.blend);draw(source,p.anim.blend)}else draw(source,1);
 if(p.action){ctx.font='bold 14px system-ui';ctx.textAlign='center';ctx.fillStyle='#fff7dd';ctx.lineWidth=3;ctx.strokeStyle='#536753';const mark=p.action==='bed'?'Z z':p.action==='stove'?'♨':p.action==='tub'?'• •':['romance-hug','romance-kiss','romance-handhold','romance-talk','romance-sit'].includes(p.action)?'♥':'♥';ctx.strokeText(mark,x,g-102-jump);ctx.fillText(mark,x,g-102-jump)}
 ctx.font='800 10px Nunito,system-ui';ctx.textAlign='center';ctx.lineWidth=3;ctx.strokeStyle='#40564b';ctx.strokeText(p.name,x,g-SPRITE.height*SPRITE.scale-jump-7);ctx.fillStyle='#fff8e8';ctx.fillText(p.name,x,g-SPRITE.height*SPRITE.scale-jump-7);
}
const leafColors=['#c9b76f','#d7a47a','#94ad78','#e1bd79'];
function drawAtmosphere(t){
 const anniversary=game.scene==='anniversary',outdoor=['street','park','anniversary'].includes(game.scene),hour=((game.minute/60)%24+24)%24,day=Math.max(0,Math.sin(clamp((hour-5)/15,0,1)*Math.PI)),night=1-day;
 if(outdoor&&night>.2){ctx.globalAlpha=night*.8;for(let i=0;i<24;i++){let x=(i*173+53)%960,y=24+(i*67)%183;rect(x,y,i%4===0?3:2,2,'#fff1c7')}ctx.globalAlpha=1}
 if(outdoor){for(let i=0;i<(anniversary?10:7);i++){let x=((i*181+t*(anniversary?.009:.016+i%2*.007))%1020)-30,y=115+(i*79+t*.009)%210;let sway=Math.sin(t/250+i)*7;rect(x+sway,y,5,3,anniversary?'#f2c1b3':leafColors[i%leafColors.length]);rect(x+sway+2,y+2,2,2,anniversary?'#f2c1b3':leafColors[i%leafColors.length])}}
 if(anniversary&&game.anniversary?.fireworksUntil>t){for(let n=0;n<4;n++){let cx=145+n*235,cy=85+(n%2)*62,age=((t-game.anniversary.fireworksAt)/500+n*.18)%1;for(let k=0;k<10;k++){let a=k*Math.PI/5,rad=age*34;rect(cx+Math.cos(a)*rad,cy+Math.sin(a)*rad,3,3,['#ffe9a5','#ffd0c2','#f8e9d0'][n%3])}}}
 if(night>.02){let a=night*(.08+Math.max(0,1-Math.abs(hour-22)/4)*.06);ctx.fillStyle=`rgba(23,35,62,${a})`;ctx.fillRect(0,0,960,450);}
}
function draw(t){
 const sc=scenes[game.scene],outdoor=sc.type==='street'||sc.type==='park'||sc.type==='anniversary';drawSky(game.scene,t);drawBackdrop(game.scene);
 // Surface textures: varied grass tufts outdoors, wide paving in town, timber inside.
 if(outdoor){const special=sc.type==='anniversary';rect(0,390,960,55,special?'#b8958a':sc.type==='park'?'#b8a27b':'#b8b49c');rect(0,390,960,5,special?'#d0a995':sc.type==='park'?'#caba96':'#c9c8a9');rect(0,sc.ground,960,110,special?'#70835f':sc.type==='park'?'#789668':'#748c68');rect(0,sc.ground,960,8,special?'#aabd82':'#a6bb81');for(let i=0;i<44;i++){let x=(i*47+13)%960,y=440+(i*37)%93;rect(x,y,7+(i%3)*2,2,special?'#91a775':'#88a273');rect(x+3,y-3,2,3,special?'#a5b987':'#95ad7d')}for(let i=0;i<14;i++){let x=(i*73+31)%960;rect(x,398,35,2,special?'#d0a995':'#d0c19d');rect(x+5,404,2,13,'#aa9979')}}
 else{rect(0,sc.ground,960,110,sc.type==='home'||sc.type==='room'||sc.type==='kitchen'||sc.type==='bathroom'?'#ae8260':'#8e6a52');rect(0,sc.ground,960,7,'#d1ac7b');for(let x=0;x<960;x+=48){rect(x,sc.ground+7,2,110,'#8f6a50');rect(x+20,sc.ground+35,15,2,'#c4946b');rect(x+5,sc.ground+78,13,2,'#c4946b')}}
 if(sc.type==='anniversary')drawAnniversaryGift(t);
 if(['home','bedroom','kitchen','bathroom'].includes(game.scene)){game.houseItems.filter(o=>o.room===game.scene).forEach(drawFurniture);drawDoor()}
 game.heroes.forEach((p,i)=>drawCharacter(p,i,t));drawAtmosphere(t);requestAnimationFrame(draw)
}
game.camera=0;if(houseRooms.includes(game.scene)){let used=[];game.heroes.forEach((p,i)=>{if(game.houseItems.some(o=>o.room===game.scene&&Math.abs(o.x-p.x)<=(furnitureDefs[o.id]?.w||40)/2+10))p.x=findClearSpot(i?790:820,used);used.push(p.x)})}game.heroes.forEach(p=>{p.y=p.y||0;p.vx=0;p.facing=p.facing||1;p.jumpTime=0;p.jumpY=0;p.anim={state:'idle',from:'idle',time:0,fromTime:0,blend:1}});
function refresh(){let names=game.heroes.map(h=>h.name);$('#heroOneName').textContent=names[0];$('#heroTwoName').textContent=names[1];$('#moneyLabel').textContent=`◈ ${game.money}`;$('#sceneTitle').textContent=scenes[game.scene].name;$('#dayLabel').textContent=`День ${game.day} · ${['Ночь','Утро','День','Вечер'][Math.floor((game.minute%1440)/360)]}`;$('#relationshipFill').style.width=`${game.relationship}%`;$('#relationshipValue').textContent=game.relationship;$('#needs').innerHTML=game.needs[game.active]&&[['Энергия','energy'],['Сытость','hunger'],['Настроение','happy']].map(([n,k])=>`<div class="need"><b>${n}</b><div class="need-meter"><i style="width:${game.needs[game.active][k]}%"></i></div></div>`).join('');$('#sceneNav').innerHTML=['home','street','park','cafe','shop'].map(id=>`<button data-scene="${id}" class="${game.scene===id?'active':''}">${{home:'Дом',street:'Улица',park:'Парк',cafe:'Кафе',shop:'Магазин'}[id]}</button>`).join('');$('#sceneNav').querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>go(b.dataset.scene));}
function go(id,paired=false){if(!scenes[id])return;const keepHands=game.holdingHands;game.scene=id;game.camera=0;const used=[];game.heroes.forEach((p,i)=>{p.x=houseRooms.includes(id)?findClearSpot(i?790:820,used):id==='anniversary'?430+i*48:260+i*65;used.push(p.x);p.vx=0;p.jumpTime=0;p.jumpY=0;p.approach=null;p.action=null;p.actionTime=0;p.facing=i===0?-1:1});game.pairRunning=null;if(paired){game.heroes[0].facing=1;game.heroes[1].facing=-1;romance(4,'Свидание началось — вы пришли вместе!')}if(keepHands){const offset=(Math.sign(game.handholdOffset)||1)*36,leader=game.heroes[game.active],follower=game.heroes[1-game.active],min=25-Math.min(0,offset),max=scenes[id].width-25-Math.max(0,offset);leader.x=clamp(leader.x,min,max);follower.x=leader.x+offset;game.handholdOffset=offset;leader.facing=follower.facing}refresh();save();notify(`Вы пришли: ${scenes[id].name}`)}

function findClearSpot(preferred,used=[]){for(let d=0;d<820;d+=5)for(const sign of [1,-1]){const x=preferred+d*sign;if(x<35||x>850||used.some(q=>Math.abs(q-x)<32))continue;if(game.houseItems.some(o=>o.room===game.scene&&Math.abs(o.x-x)<=(furnitureDefs[o.id]?.w||40)/2+10))continue;return x}return 820}
function roomExit(){return ({home:'bedroom',bedroom:'kitchen',kitchen:'bathroom',bathroom:'home'})[game.scene]}
function objectAt(x){return game.houseItems.find(o=>o.room===game.scene&&Math.abs(o.x-x)<=(furnitureDefs[o.id]?.w||0)*.5+10)}
function houseInteract(){const p=game.heroes[game.active];if(!houseRooms.includes(game.scene))return false;
 if(Math.abs(p.x-906)<150&&Math.abs(p.x-906)>=55){p.approach={x:875,object:'__door'};p.facing=1;notify('Подходим к двери…');return true}
 if(Math.abs(p.x-906)<55){const dest=roomExit();go(dest);return true}
 const obj=objectAt(p.x);if(!obj){const nearest=game.houseItems.filter(o=>o.room===game.scene).sort((a,b)=>Math.abs(a.x-p.x)-Math.abs(b.x-p.x))[0];if(nearest&&Math.abs(nearest.x-p.x)<150){const d=furnitureDefs[nearest.id],side=p.x<=nearest.x?-1:1;p.approach={x:nearest.x+side*(d.w/2+10),object:nearest.id};p.facing=side===-1?1:-1;notify(`Подходим к предмету: ${d.name.toLowerCase()}…`);return true}return false}
 const d=furnitureDefs[obj.id];if(Math.abs(p.x-obj.x)>d.w/2+32){const side=p.x<obj.x?-1:1;p.approach={x:obj.x+side*(d.w/2+10),object:obj.id};p.facing=side===-1?1:-1;return true}performFurniture(obj,p);return true;
}
function performFurniture(o,p){const n=game.needs[game.active];p.approach=null;p.action=o.id;p.actionTime=1.4;p.facing=o.x>=p.x?1:-1;const done=(msg)=>{notify(msg);save();refresh()};
 if(o.id==='bed'){game.needs.forEach(v=>v.energy=100);game.minute=480;done('Вы сладко поспали. Энергия восстановлена!')}
 else if(['sofa','armchair','chair','dining_table','coffee_table'].includes(o.id)){n.happy=clamp(n.happy+12,0,100);done('Вы устроились поудобнее и отдохнули.')}
 else if(o.id==='wardrobe'){p.action=null;wardrobe()}
 else if(o.id==='fridge'){const foods=game.inventory.filter(i=>['tea','cake','meal'].includes(i.id)&&i.count>0);if(!foods.length){done('В холодильнике пока пусто. Можно купить продукты в магазине.');return}openModal('Что взять из холодильника?',`<p>Небольшой перекус восстановит сытость.</p><div class="item-list">${foods.map(i=>`<div class="item"><div>${i.name}<small>В запасе: ${i.count}</small></div><button data-eat="${i.id}">Взять</button></div>`).join('')}</div>`)}
 else if(o.id==='stove'){const ing=game.inventory.find(i=>i.id==='meal'&&i.count>0);if(ing){ing.count--;n.hunger=clamp(n.hunger+32,0,100);done('Вы приготовили тёплый обед!')}else{game.inventory.push({id:'meal',name:'Домашний обед',count:1,icon:'🍲',price:0});done('Готово! Домашний обед появился в рюкзаке.')}}
 else if(o.id==='tub'){n.happy=clamp(n.happy+16,0,100);n.energy=clamp(n.energy+5,0,100);done('Тёплая ванна помогла расслабиться.')}
 else if(o.id==='sink'){n.happy=clamp(n.happy+3,0,100);done('Вы умылись прохладной водой.')}
 else if(o.id==='toilet'){n.happy=clamp(n.happy+2,0,100);done('Вы чувствуете себя лучше.')}
 else if(o.id==='plant'){n.happy=clamp(n.happy+4,0,100);done('Цветок полит, а комната стала уютнее.')}
 else if(o.id==='lamp'){done('В комнате зажёгся тёплый свет.')}
 else {n.happy=clamp(n.happy+6,0,100);done('Вы провели время с любимой книгой.')}
}
function placeFurnitureAt(screenX,screenY){if(!game.placing)return;const rect=canvas.getBoundingClientRect();if(screenY<rect.top+rect.height*.67||screenY>rect.top+rect.height*.86){notify('Выберите место на свободном полу комнаты.');return}const move=typeof game.placing==='object',id=move?game.placing.id:game.placing,d=furnitureDefs[id],worldX=(screenX-rect.left)*canvas.width/rect.width+game.camera,x=Math.round(clamp(worldX,d.w/2+20,830-d.w/2)),moving=move?game.placing.item:null;if(!houseRooms.includes(game.scene)){notify('Мебель можно размещать только дома.');return}if(game.houseItems.some(o=>o!==moving&&o.room===game.scene&&Math.abs(o.x-x)<(d.w+(furnitureDefs[o.id]?.w||0))/2+12)){notify('Здесь мебель столкнётся с другой или загородит проход.');return}if(moving){moving.room=game.scene;moving.x=x}else{const inv=game.inventory.find(i=>i.id===id&&i.count>0);if(!inv){notify('Этот предмет отсутствует в рюкзаке.');game.placing=null;return}inv.count--;game.houseItems.push({id,room:game.scene,x})}game.placing=null;save();refresh();notify(`${d.name} ${moving?'перемещён':'поставлен'} и сохранён.`)}
canvas.addEventListener('click',e=>{if(game.placing){placeFurnitureAt(e.clientX,e.clientY);return}if(!houseRooms.includes(game.scene))return;const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)*canvas.width/r.width+game.camera,y=(e.clientY-r.top)*canvas.height/r.height,p=game.heroes[game.active];if(y<scenes[game.scene].ground-125||y>scenes[game.scene].ground+10)return;if(x>865){p.approach={x:875,object:'__door'};p.facing=1;if(game.holdingHands){const q=game.heroes[1-game.active];q.approach={x:875+(Number(game.handholdOffset)||0),pair:true};q.facing=1}return}const o=game.houseItems.filter(o=>o.room===game.scene).sort((a,b)=>Math.abs(a.x-x)-Math.abs(b.x-x))[0];if(!o||Math.abs(o.x-x)>(furnitureDefs[o.id]?.w||0)/2+42)return;const side=p.x<o.x?-1:1,d=furnitureDefs[o.id];p.facing=side<0?1:-1;if(Math.abs(p.x-o.x)<=d.w/2+32)performFurniture(o,p);else p.approach={x:o.x+side*(d.w/2+10),object:o.id}});
function startJump(){if(game.holdingHands){notify('Чтобы прыгнуть, сначала отпустите руки.');return}const p=game.heroes[game.active],n=game.needs[game.active];if(p.jumpTime>0||n.energy<=8)return;p.jumpTime=.46;n.energy=clamp(n.energy-1,0,100);save();refresh()}
function update(now){
 let dt=Math.min((now-last)/16.67,2);last=now;clock+=dt;
 const heldMove=game.holdingHands&&!modalOpen()&&game.heroes.every(h=>!h.actionTime&&!h.approach);
 if(heldMove){const leader=game.heroes[game.handholdLeader],follower=game.heroes[1-game.handholdLeader],offset=Number(game.handholdOffset)||0,dir=(keys.ArrowLeft||keys.KeyA?-1:0)+(keys.ArrowRight||keys.KeyD?1:0),min=25-Math.min(0,offset),max=scenes[game.scene].width-25-Math.max(0,offset),next=clamp(leader.x+dir*3.1*dt,min,max),delta=next-leader.x;leader.x=next;follower.x=next+offset;leader.vx=follower.vx=dt?delta/dt:0;if(dir){leader.facing=follower.facing=dir}}
 for(let i=0;i<game.heroes.length;i++){
  let p=game.heroes[i];if(!heldMove){p.vx=0;
   if((i===game.active||p.approach?.pair)&&!modalOpen()&&!p.actionTime){if(p.approach){let delta=p.approach.x-p.x;if(Math.abs(delta)<3){p.x=p.approach.x;const target=p.approach.object&&game.houseItems.find(o=>o.id===p.approach.object&&o.room===game.scene),pairMove=p.approach.pair,object=p.approach.object;p.approach=null;if(target)performFurniture(target,p);else if(object==='__anniversary_gift')openAnniversaryGift();else if(!pairMove&&object==='__door')go(roomExit())}else{p.vx=Math.sign(delta)*Math.min(3.1,Math.abs(delta));p.facing=Math.sign(delta)}}else if(i===game.active){if(keys.ArrowLeft||keys.KeyA){p.vx=-3.1;p.facing=-1}if(keys.ArrowRight||keys.KeyD){p.vx=3.1;p.facing=1}}}
   p.x=clamp(p.x+p.vx*dt,25,scenes[game.scene].width-25);
  }
  p.jumpTime=Math.max(0,(p.jumpTime||0)-dt/60);let progress=1-p.jumpTime/.46;p.jumpY=p.jumpTime>0?Math.sin(clamp(progress,0,1)*Math.PI)*34:0;
  const gestureState=p.action?.startsWith('romance-')?({talk:'talk',compliment:'talk',joke:'talk',hug:'hug',handhold:'handhold',kiss:'kiss',sit:'sit'}[p.action.slice(8)]):null;const heldState=game.holdingHands?(Math.abs(p.vx)>.1?'handhold_walk':'handhold'):null;const next=heldState||gestureState|| (p.jumpTime>0?'jump':Math.abs(p.vx)>.1?'walk':'idle');
  if(!p.anim)p.anim={state:'idle',from:'idle',time:0,fromTime:0,blend:1};
  if(next!==p.anim.state){p.anim.from=p.anim.state;p.anim.fromTime=p.anim.time;p.anim.state=next;p.anim.time=0;p.anim.blend=0}
  else p.anim.blend=clamp(p.anim.blend+dt/10.8,0,1);
  p.anim.time+=dt/60;
  if(p.actionTime>0){p.actionTime=Math.max(0,p.actionTime-dt/60);if(!p.actionTime){if(!(game.holdingHands&&p.action==='romance-handhold'))p.action=null;p.pairKind=null;p.anim.state=game.holdingHands?'handhold':'idle';p.anim.from=p.anim.state;p.anim.time=0;p.anim.blend=1}}
 }
if(game.pairRunning&&!game.pairRunning.started&&game.heroes.every(h=>!h.approach&&h.pairKind))finishPair();if(game.pairRunning?.started&&game.heroes.every(h=>!h.actionTime)){game.pairRunning=null;save();if(game.anniversary.finalPending){const ending=game.anniversary.finalPending==='ending';game.anniversary.finalPending=false;game.anniversary.finalDone=true;save();if(ending){closeModal();go('park');notify('Вечер окончен: поцелуй, огни и дорога домой.')}else openModal('С нашей первой годовщиной',`<p>Под звёздным небом вечер согревает объятием и огнями. Вот ваше послание.</p><div class="actions"><button class="primary" data-letter>Открыть письмо</button></div>`)}}
 let h=game.heroes[game.active];game.camera=clamp(h.x-480,0,scenes[game.scene].width-960);game.minute=(game.minute+dt*.11)%1440;$('#dayLabel').textContent=`День ${game.day} · ${['Ночь','Утро','День','Вечер'][Math.floor((game.minute%1440)/360)]}`;
 if(clock>600){clock=0;game.needs.forEach(n=>{n.hunger=clamp(n.hunger-.7,0,100);n.energy=clamp(n.energy-.3,0,100);n.happy=clamp(n.happy-.15,0,100)});if(game.minute<2)game.day++;save();refresh()}
 requestAnimationFrame(update)
}
let activeModal='';function modalOpen(){return !$('#modal').classList.contains('hidden')}
function openModal(title,body){if(!modalOpen())modalReturnFocus=document.activeElement;$('#modalContent').innerHTML=`<h2 id="modal-title">${title}</h2>${body}`;$('#modal').classList.remove('hidden');activeModal=title;requestAnimationFrame(()=>$('#modal').querySelector('button:not(:disabled),input:not(:disabled),select:not(:disabled)')?.focus())}
let modalReturnFocus=null;function closeModal(){ $('#modal').classList.add('hidden');activeModal='';keys={};if(modalReturnFocus?.isConnected)modalReturnFocus.focus();else document.querySelector('[data-menu="inventory"]')?.focus();modalReturnFocus=null;}
$('#closeModal').onclick=closeModal;$('#modal').onclick=e=>{if(e.target.id==='modal')closeModal()};$('#modal').addEventListener('keydown',e=>{if(e.key!=='Tab')return;const els=[...$('#modal').querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),[tabindex="0"]')];if(!els.length)return;const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}});function mainMenu(){openModal('Главное меню',`<p>Продолжите историю или проведите особенный вечер вдвоём.</p><div class="actions"><button class="primary" data-resume>Продолжить игру</button><button class="soft" data-anniversary>История годовщины</button><button class="soft" data-new>Начать новую игру</button></div>`)}$('#pauseBtn').onclick=()=>openModal('Пауза',`<p>Игра приостановлена. Отдохните или откройте главное меню.</p><div class="actions"><button class="primary" data-resume>Продолжить</button><button class="soft" data-main-menu>Главное меню</button><button class="soft" data-new>Начать заново</button></div>`);
function setup(){openModal('Добро пожаловать домой',`<p>Давайте познакомимся с героями вашей истории. Все данные сохраняются только в этом браузере.</p><section class="hero-edit"><h3>Первый герой</h3><label class="field">Имя<input id="n1" maxlength="40" value="${escapeHtml(game.heroes[0].name)}"></label><div class="row"><label class="field">Тон кожи<select id="skin1"><option value="#e6ad86">Тёплый</option><option value="#f0c9a2">Светлый</option><option value="#a96f50">Тёмный</option></select></label><label class="field">Цвет волос<select id="hair1"><option value="#63483c">Каштановые</option><option value="#d8a657">Медовые</option><option value="#43384a">Тёмные</option></select></label></div></section><section class="hero-edit"><h3>Второй герой</h3><label class="field">Имя<input id="n2" maxlength="40" value="${escapeHtml(game.heroes[1].name)}"></label><div class="row"><label class="field">Тон кожи<select id="skin2"><option value="#c98e6b">Тёплый</option><option value="#f0c9a2">Светлый</option><option value="#80533e">Тёмный</option></select></label><label class="field">Цвет волос<select id="hair2"><option value="#382f36">Тёмные</option><option value="#9b6648">Каштановые</option><option value="#d2aa65">Медовые</option></select></label></div></section><button class="primary" data-begin>Начать нашу историю</button>`)}
function inventory(){let entries=game.inventory.filter(x=>x.count>0).map(x=>`<div class="item"><div>${x.icon} ${x.name}<small>В рюкзаке: ${x.count}</small></div><button data-use="${x.id}">Использовать</button></div>`).join('')||'<p>Пока пусто. Загляните в лавку!</p>';openModal('Рюкзак',`<p>Небольшие вещи для хорошего дня.</p><div class="item-list">${entries}</div>`)}
function wardrobe(){const p=game.heroes[game.active],names={long:'Длинные',bob:'Каре',curls:'Кудри',crop:'Короткие'},outfits={cardigan:['Кардиган','#d77d72','#596f84'],overalls:['Комбинезон','#678c77','#46556a'],dress:['Платье','#bd7890','#74536e']};openModal('Гардероб',`<p>Одежда и причёска героя ${game.active+1}: <b>${escapeHtml(p.name)}</b>.</p><div class="item-list"><div class="item"><div>Выбрать героя</div><div>${game.heroes.map((h,i)=>`<button data-wardrobe-hero="${i}">${i===game.active?'● ':''}${escapeHtml(h.name)}</button>`).join(' ')}</div></div><div class="item"><div>Причёска</div><div>${Object.entries(names).map(([id,n])=>`<button data-hair-style="${id}">${p.hairStyle===id?'● ':''}${n}</button>`).join(' ')}</div></div><div class="item"><div>Одежда</div><div>${Object.entries(outfits).map(([id,o])=>`<button data-outfit="${id}">${p.outfit===id?'● ':''}${o[0]}</button>`).join(' ')}</div></div></div>`)}
document.body.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.menu==='romance')romanceMenu();if(b.dataset.menu==='main')mainMenu();if(b.hasAttribute('data-main-menu')){closeModal();mainMenu()}if(b.dataset.romance){if(b.dataset.romance==='handhold'&&game.holdingHands){closeModal();releaseHands();return}const data={talk:[3,'Вы поговорили по душам.'],compliment:[3,'Тёплый комплимент поднял настроение.'],joke:[2,'Вы вместе посмеялись.'],hug:[5,'Объятия сделали этот день теплее.'],handhold:[4,'Вы прогулялись, держась за руки.'],kiss:[6,'Нежный поцелуй останется приятным воспоминанием.'],sit:[3,'Тихий отдых рядом помог вам сблизиться.']}[b.dataset.romance];closeModal();beginPair(b.dataset.romance,data[0],data[1])}if(b.dataset.gift){const item=game.inventory.find(x=>x.id===b.dataset.gift&&x.count>0);if(!item){notify('Этот предмет уже закончился.');return}const name=item.name;item.count--;if(item.count===0)game.inventory=game.inventory.filter(x=>x!==item);closeModal();beginPair('compliment',item.id==='flower'?9:5,`${name} стал приятным подарком!`);save()}if(b.dataset.date){const id=b.dataset.date;if(!['park','cafe'].includes(id))return;closeModal();go(id,true)}});
const stock=[{id:'tea',name:'Чай с мёдом',icon:'☕',price:12,effect:'hunger'},{id:'flower',name:'Полевой букет',icon:'✿',price:18,effect:'love'},{id:'cake',name:'Кусочек торта',icon:'🍰',price:20,effect:'happy'},{id:'plant',name:'Комнатный цветок',icon:'♧',price:35,effect:'furniture'},{id:'lamp',name:'Тёплый торшер',icon:'✧',price:48,effect:'furniture'},{id:'armchair',name:'Мягкое кресло',icon:'▰',price:52,effect:'furniture'},{id:'bookshelf',name:'Книжный шкаф',icon:'▤',price:68,effect:'furniture'},{id:'chair',name:'Деревянный стул',icon:'▰',price:24,effect:'furniture'},{id:'coffee_table',name:'Журнальный столик',icon:'▱',price:38,effect:'furniture'}];
