function interact(){if(game.scene==='anniversary'){anniversaryInteract();return}if(houseInteract())return;romanceMenu()}
function romanceMenu(){const places=[['park','Прогуляться в парке'],['cafe','Сходить в кафе']];const actions=[['talk','Поговорить по душам',3],['compliment','Сказать комплимент',3],['joke','Рассказать шутку',2],['hug','Обняться',5],['handhold','Взяться за руки',4],['kiss','Поцеловаться',6],['sit','Посидеть рядом',3]];let gifts=game.inventory.filter(i=>i.count>0&&!furnitureDefs[i.id]);openModal('Время вдвоём',`<p>Близость: <b>${game.relationship}/100</b>. Выберите настоящее совместное действие.</p><div class="item-list">${actions.map(([id,name])=>`<div class="item"><div>${name}</div><button data-romance="${id}">${id==='handhold'&&game.holdingHands?'Отпустить руки':'Вместе'}</button></div>`).join('')}${gifts.map(i=>`<div class="item"><div>Подарить: ${i.icon||'✿'} ${i.name}<small>В рюкзаке: ${i.count}</small></div><button data-gift="${i.id}">Подарить</button></div>`).join('')||'<p>Нет вещей для подарка. Букет, чай и десерт можно купить в лавке.</p>'}${places.map(([id,name])=>`<div class="item"><div>${name}</div><button data-date="${id}">Пригласить</button></div>`).join('')}<div class="item"><div>Особый вечер годовщины<small>Прогулка, подарок и письмо</small></div><button data-anniversary>Начать</button></div></div>`)}
function releaseHands(showMessage=true){if(!game.holdingHands)return;game.holdingHands=false;game.handholdOffset=0;game.heroes.forEach(p=>{if(p.action==='romance-handhold'){p.action=null;p.actionTime=0;p.anim.state='idle';p.anim.from='idle';p.anim.time=0;p.anim.blend=1}});save();refresh();if(showMessage)notify('Вы отпустили руки.')}
function beginPair(kind,points,message,force=false){if(game.holdingHands&&kind!=='handhold')releaseHands(false);const a=game.active,b=1-a,p=game.heroes[a],q=game.heroes[b],scene=game.scene;if(!force&&['kiss','hug'].includes(kind)&&game.relationship<15){notify('Сначала укрепите близость: поговорите, скажите комплимент или подарите что-нибудь.');return}let mid=clamp((p.x+q.x)/2,50,scenes[scene].width-50),gap=kind==='handhold'?18:kind==='sit'?26:22;let left=mid-gap,right=mid+gap;p.action=null;q.action=null;p.actionTime=0;q.actionTime=0;p.approach={x:a===0?left:right,pair:true};q.approach={x:b===0?left:right,pair:true};p.pairKind=kind;q.pairKind=kind;p.facing=p.x<=q.x?1:-1;q.facing=-p.facing;game.pairRunning={kind,points,message,started:false};notify('Персонажи подходят друг к другу…');save()}
function finishPair(){let pair=game.pairRunning;if(!pair||pair.started)return;pair.started=true;let state={talk:'talk',compliment:'talk',joke:'talk',hug:'hug',handhold:'handhold',kiss:'kiss',sit:'sit'}[pair.kind];const faceRight=game.heroes[0].x<=game.heroes[1].x;game.heroes.forEach((p,i)=>{p.approach=null;p.action=`romance-${pair.kind}`;p.actionTime=pair.kind==='sit'?4:game.anniversary.finalPending==='ending'?5.3:2.1;p.facing=i===0?(faceRight?1:-1):(faceRight?-1:1);p.anim.from=p.anim.state;p.anim.fromTime=p.anim.time;p.anim.state=state;p.anim.time=0;p.anim.blend=0});if(pair.kind==='handhold'){game.holdingHands=true;game.handholdLeader=game.active;game.handholdOffset=game.heroes[1-game.active].x-game.heroes[game.active].x}game.needs.forEach(n=>n.happy=clamp(n.happy+Math.max(1,Math.ceil(pair.points/2)),0,100));game.relationship=clamp(game.relationship+pair.points,0,100);notify(pair.message);save();refresh()}
function need(k,n){let v=game.needs[game.active];v[k]=clamp(v[k]+n,0,100);notify('Самое время немного позаботиться о себе.');refresh()}
function romance(n,msg){game.relationship=clamp(game.relationship+n,0,100);game.needs.forEach(x=>x.happy=clamp(x.happy+Math.ceil(n/2),0,100));notify(msg);refresh();save()}
function decorate(){const owned=game.inventory.filter(i=>furnitureDefs[i.id]&&i.count>0).map(i=>`<div class="item"><div>${i.icon||furnitureDefs[i.id].icon} ${i.name}<small>В рюкзаке: ${i.count}</small></div><button data-place="${i.id}">Разместить</button></div>`).join('');const placed=game.houseItems.map((o,i)=>`<div class="item"><div>${furnitureDefs[o.id].name}<small>${scenes[o.room].name} · x ${Math.round(o.x)}</small></div><button data-move="${i}">Переместить</button></div>`).join('');openModal('Дом и мебель',`<p>Выберите комнату, чтобы поставить новый предмет. Чтобы передвинуть мебель, нажмите «Переместить», затем кликните по свободному месту на полу.</p><div class="actions">${houseRooms.map(id=>`<button class="soft" data-room="${id}">${scenes[id].name.replace('Наш дом · ','')}</button>`).join('')}</div><h3>Мебель в рюкзаке</h3><div class="item-list">${owned||'<p>Пока пусто. Купить мебель можно в магазине.</p>'}</div><h3>Предметы дома</h3><div class="item-list">${placed}</div>`)}
function settings(){openModal('Настройки',`<p>Управление: A / D или ← / → — ходьба, E — действие, Tab — сменить героя. На телефоне используйте кнопки на экране.</p><h3>Имена персонажей</h3><div class="row"><label class="field">Первый герой<input id="setting-name-0" maxlength="40" value="${escapeHtml(game.heroes[0].name)}"></label><label class="field">Второй герой<input id="setting-name-1" maxlength="40" value="${escapeHtml(game.heroes[1].name)}"></label></div><button class="soft" data-save-names>Сохранить имена</button><label class="field"><span>Громкость: <b id="volumeNum">${game.settings.volume}</b>%</span><input id="volume" type="range" min="0" max="100" value="${game.settings.volume}"></label><label class="field"><span><input id="music" type="checkbox" ${game.settings.music?'checked':''}> Атмосферные звуки (звуковой дорожки нет)</span></label><button class="soft" data-reset>Удалить сохранение и начать заново…</button>`)}
document.body.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.menu==='inventory')inventory();if(b.dataset.menu==='wardrobe')wardrobe();if(b.hasAttribute('data-wardrobe-hero')){game.active=Number(b.dataset.wardrobeHero);save();refresh();wardrobe()}if(b.dataset.hairStyle){game.heroes[game.active].hairStyle=b.dataset.hairStyle;save();refresh();wardrobe()}if(b.dataset.outfit){let presets={cardigan:['#d77d72','#596f84'],overalls:['#678c77','#46556a'],dress:['#bd7890','#74536e']};game.heroes[game.active].outfit=b.dataset.outfit;[game.heroes[game.active].shirt,game.heroes[game.active].pants]=presets[b.dataset.outfit];save();refresh();wardrobe()}if(b.dataset.menu==='map')mapMenu();if(b.dataset.menu==='shop')shop();if(b.dataset.menu==='decorate')decorate();if(b.dataset.menu==='settings')settings();if(b.hasAttribute('data-resume'))closeModal();if(b.hasAttribute('data-new')){if(confirm('Начать новую игру? Текущий прогресс будет заменён.')){localStorage.removeItem('our-little-world-save');game=fresh();game.camera=0;closeModal();setup();refresh()}}if(b.hasAttribute('data-begin')){game.heroes[0].name=$('#n1').value.trim();game.heroes[1].name=$('#n2').value.trim();game.heroes[0].skin=$('#skin1').value;game.heroes[0].hair=$('#hair1').value;game.heroes[1].skin=$('#skin2').value;game.heroes[1].hair=$('#hair2').value;closeModal();refresh();save();notify('Добро пожаловать в ваш маленький мир!')}if(b.dataset.go){let id=b.dataset.go;closeModal();go(id)}if(b.dataset.use){let i=game.inventory.find(x=>x.id===b.dataset.use&&x.count>0);if(!i)return; i.count--;if(i.id==='tea'||i.id==='cake')need('hunger',24);if(i.id==='cake')need('happy',10);if(i.id==='flower')romance(5,'Подарок стал поводом для улыбки!');save();inventory();refresh()}if(b.dataset.buy){let i=stock.find(x=>x.id===b.dataset.buy);if(game.money<i.price)return notify('Не хватает монет.');game.money-=i.price;let old=game.inventory.find(x=>x.id===i.id);if(old)old.count++;else game.inventory.push({id:i.id,name:i.name,count:1,icon:i.icon,price:i.price});if(i.effect==='furniture'&&!game.furniture.includes(i.id))game.furniture.push(i.id);$('#moneyLabel').textContent=`◈ ${game.money}`;shop();save();notify(`${i.name} добавлено в ваши вещи!`)}if(b.dataset.place){game.placing=b.dataset.place;closeModal();notify('Кликните по свободному полу, чтобы поставить мебель.')}if(b.dataset.move){let item=game.houseItems[Number(b.dataset.move)];if(item){game.placing={id:item.id,item};closeModal();notify('Кликните по свободному полу, чтобы переместить предмет.')}}if(b.dataset.eat){let food=game.inventory.find(i=>i.id===b.dataset.eat&&i.count>0);if(food){food.count--;game.needs[game.active].hunger=clamp(game.needs[game.active].hunger+28,0,100);closeModal();save();refresh();notify(`Вы поели: ${food.name}.`)}}if(b.dataset.room){let id=b.dataset.room;closeModal();go(id)}if(b.hasAttribute('data-reset')){if(confirm('Удалить только сохранение Our Little World в этом браузере и начать заново?')){localStorage.removeItem('our-little-world-save');game=fresh();game.camera=0;closeModal();refresh();setup()}}});
document.body.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-anniversary'))startAnniversary();if(b.hasAttribute('data-anniversary-start'))beginAnniversary(false);if(b.hasAttribute('data-anniversary-skip'))beginAnniversary(true);if(b.hasAttribute('data-anniversary-walk')){closeModal();beginPair('handhold',5,`Вечер начался — ${annName(0)} и ${annName(1)} идут рядом.`)}if(b.hasAttribute('data-letter'))letterMenu();if(b.hasAttribute('data-anniversary-end')){game.anniversary.finalPending='ending';game.anniversary.fireworksAt=performance.now();game.anniversary.fireworksUntil=performance.now()+5200;closeModal();beginPair('kiss',8,'Вечер заканчивается поцелуем под праздничными огнями.',true)}if(b.dataset.anniversaryCouple){closeModal();beginPair(b.dataset.anniversaryCouple,b.dataset.anniversaryCouple==='sit'?4:5,b.dataset.anniversaryCouple==='sit'?'Вы устроились рядом на скамейке.':'Вы поговорили о том, что дорого вам обоим.')}if(b.hasAttribute('data-anniversary-gift')){closeModal();const p=game.heroes[game.active];if(Math.abs(p.x-865)<68)openAnniversaryGift();else{p.approach={x:p.x<865?823:907,object:'__anniversary_gift'};p.facing=p.x<865?1:-1;notify('Подходим к праздничной коробке…')}}if(b.hasAttribute('data-anniversary-finale')){if(!game.anniversary.presentOpened){notify('Сначала откройте подарок из коробки.');return}closeModal();game.anniversary.finalPending=true;game.anniversary.fireworksAt=performance.now();game.anniversary.fireworksUntil=performance.now()+5200;beginPair('hug',9,'Под звёздами вы обнялись, и в небе зажглись огни.',true)}if(b.hasAttribute('data-save-names')){game.heroes[0].name=$('#setting-name-0').value.slice(0,40);game.heroes[1].name=$('#setting-name-1').value.slice(0,40);save();refresh();settings();notify('Имена персонажей сохранены.')}});document.body.addEventListener('input',e=>{if(e.target.id==='volume'){game.settings.volume=+e.target.value;$('#volumeNum').textContent=e.target.value;save()}});document.body.addEventListener('change',e=>{if(e.target.id==='music'){game.settings.music=e.target.checked;save()}});
canvas.addEventListener('click',e=>{if(game.scene!=='anniversary'||game.anniversary.presentOpened)return;const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)*canvas.width/r.width+game.camera,y=(e.clientY-r.top)*canvas.height/r.height,p=game.heroes[game.active];if(Math.abs(x-865)<58&&y>scenes.anniversary.ground-75){const dx=865-p.x;if(Math.abs(dx)<68)openAnniversaryGift();else{p.approach={x:dx>0?823:907,object:'__anniversary_gift'};p.facing=Math.sign(dx);notify('Подходим к праздничной коробке…')}}});
window.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp',' '].includes(e.key))e.preventDefault();if(e.key==='Escape'){if(modalOpen())closeModal();else $('#pauseBtn').click();return}if(modalOpen())return;if(e.code==='Tab'){e.preventDefault();game.active=1-game.active;if(game.holdingHands){game.handholdLeader=game.active;game.handholdOffset=game.heroes[1-game.active].x-game.heroes[game.active].x}game.heroes[game.active].facing=game.heroes[1-game.active].x>=game.heroes[game.active].x?1:-1;refresh()}else if(e.code==='KeyE'||e.key==='Enter')interact();else if(e.code==='Space'||e.code==='ArrowUp'||e.code==='KeyW'){if(!e.repeat)startJump()}keys[e.code]=true;keys[e.key]=true});window.addEventListener('keyup',e=>{keys[e.code]=false;keys[e.key]=false});window.addEventListener('blur',()=>keys={});document.querySelectorAll('.mobile-controls button').forEach(b=>{let down=e=>{e.preventDefault();if(b.dataset.key){keys[b.dataset.key]=true;return}if(b.dataset.action==='switch'){game.active=1-game.active;if(game.holdingHands){game.handholdLeader=game.active;game.handholdOffset=game.heroes[1-game.active].x-game.heroes[game.active].x}refresh()}if(b.dataset.action==='interact')interact();if(b.dataset.action==='jump')startJump()};let up=()=>{if(b.dataset.key)keys[b.dataset.key]=false};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);b.addEventListener('pointerleave',up)});
window.addEventListener('beforeunload',save);refresh();if(!localStorage.getItem('our-little-world-save'))setup();requestAnimationFrame(draw);requestAnimationFrame(update);
